import std.io
import std.string

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let a = string.parseInt("12a")
    match a {
        Some(v) => { io.println("junk-bad ${v}") }
        None => { io.println("junk-none") }
    }
    let b = string.parseInt(" 12")
    match b {
        Some(v) => { io.println("space-bad ${v}") }
        None => { io.println("space-none") }
    }
    let c = string.parseFloat("abc")
    match c {
        Some(v) => { io.println("abc-bad ${v}") }
        None => { io.println("abc-none") }
    }
    let d = string.parseFloat("1.5e")
    match d {
        Some(v) => { io.println("exp-bad ${v}") }
        None => { io.println("exp-none") }
    }
    return Ok(())
}
